// frontend/src/pages/Register.jsx
import React, { useState } from 'react';
import axios from 'axios';
import './Register.css';

const ciudades = ["Bogotá", "Medellín", "Cali", "Barranquilla", "Cartagena"];
const departamentos = ["Cundinamarca", "Antioquia", "Valle del Cauca", "Atlántico", "Bolívar"];

export default function Register() {
  const [form, setForm] = useState({
    nombre: '',
    apellido: '',
    correo: '',
    telefono: '',
    ciudad: '',
    departamento: '',
    contraseña: '',
    confirmar: '',
    rol: 'comprador',
    terminos: false,
    noticias: false
  });
  const [msg, setMsg] = useState('');
  const handleChange = e => {
    const { name, value, type, checked } = e.target;
    setForm({ ...form, [name]: type === 'checkbox' ? checked : value });
  };
  const handleRole = rol => setForm({ ...form, rol });
  const handleSubmit = async e => {
    e.preventDefault();
    if (!form.terminos) {
      setMsg('Debes aceptar los términos y condiciones.');
      return;
    }
    if (form.contraseña !== form.confirmar) {
      setMsg('Las contraseñas no coinciden.');
      return;
    }
    try {
      await axios.post('http://localhost:3000/api/auth/register', form);
      setMsg('¡Registro exitoso! Ahora puedes iniciar sesión.');
    } catch (err) {
      setMsg(err.response?.data?.msg || 'Error en el registro');
    }
  };
  return (
    <form className="register-container" onSubmit={handleSubmit}>
      <div className="register-title">Únete a Artisa</div>
      <div className="register-subtitle">Crea tu cuenta y forma parte de nuestra comunidad artesanal</div>
      <div className="form-section-title">¿Cómo quieres usar Artisa? *</div>
      <div className="role-options">
        <div className={`role-card${form.rol === 'comprador' ? ' selected' : ''}`} onClick={() => handleRole('comprador')}>
          <input type="radio" name="rol" checked={form.rol === 'comprador'} readOnly />
          <div>
            <b>Comprador</b>
            <div style={{fontSize: '0.95em', color: '#92400E'}}>Quiero comprar productos artesanales únicos</div>
          </div>
        </div>
        <div className={`role-card${form.rol === 'artesano' ? ' selected' : ''}`} onClick={() => handleRole('artesano')}>
          <input type="radio" name="rol" checked={form.rol === 'artesano'} readOnly />
          <div>
            <b>Artesano</b>
            <div style={{fontSize: '0.95em', color: '#92400E'}}>Quiero vender mis productos artesanales</div>
          </div>
        </div>
      </div>
      <div className="form-section-title">Información Personal</div>
      <div className="form-row">
        <input name="nombre" placeholder="Nombre *" value={form.nombre} onChange={handleChange} required />
        <input name="apellido" placeholder="Apellido *" value={form.apellido} onChange={handleChange} required />
      </div>
      <input name="correo" type="email" placeholder="Correo Electrónico *" value={form.correo} onChange={handleChange} required />
      <input name="telefono" placeholder="Teléfono *" value={form.telefono} onChange={handleChange} required />
      <div className="form-row">
        <select name="ciudad" value={form.ciudad} onChange={handleChange} required>
          <option value="">Selecciona tu ciudad</option>
          {ciudades.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <select name="departamento" value={form.departamento} onChange={handleChange} required>
          <option value="">Selecciona tu departamento</option>
          {departamentos.map(d => <option key={d} value={d}>{d}</option>)}
        </select>
      </div>
      <div className="form-section-title">Seguridad</div>
      <input name="contraseña" type="password" placeholder="Contraseña * (Mínimo 8 caracteres)" value={form.contraseña} onChange={handleChange} minLength={8} required />
      <input name="confirmar" type="password" placeholder="Confirmar Contraseña *" value={form.confirmar} onChange={handleChange} minLength={8} required />
      <div className="checkbox-row">
        <input type="checkbox" name="terminos" checked={form.terminos} onChange={handleChange} required />
        <label>Acepto los <a href="#" style={{color:'#EF6210'}}>términos y condiciones</a> y la <a href="#" style={{color:'#EF6210'}}>política de privacidad</a> de Artisa *</label>
      </div>
      <div className="checkbox-row">
        <input type="checkbox" name="noticias" checked={form.noticias} onChange={handleChange} />
        <label>Quiero recibir noticias sobre nuevos productos, historias de artesanos y ofertas especiales</label>
      </div>
      <button className="register-btn" type="submit">Crear Mi Cuenta</button>
      {msg && <div className="register-msg">{msg}</div>}
    </form>
  );
}
